custom_qss:
/* ============================================================
   COBALT WEAVE — blue companion to Branded Bronze. Tiled banding
   (spread:repeat diagonal ramps) on the window and docks, double-
   border frames, letter-spaced labels, inverted selection. Cobalt
   + ice on deep navy. Icons at 18px.
   ============================================================ */

* { color: #dce6f7; letter-spacing: 1px; }
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent; border: none;
}

/* window: tiled diagonal weave */
QMainWindow { background: qlineargradient(x1:0, y1:0, x2:0.25, y2:0.25, spread:repeat, stop:0 #152a4a, stop:1 #070c16) !important; border: none; }
QDialog { background: #070c16 !important; border: 3px solid #1c2c4a; }

/* menubar: oversized tracking, dim selected (inverted) */
QMenuBar { background: #0a1220 !important; border: none; border-bottom: 1px solid #1c2c4a; }
QMenuBar::item { padding: 5px 14px; background: transparent !important; color: #5f7ba3; letter-spacing: 3px; }
QMenuBar::item:selected { background: #0a1220 !important; color: #5f7ba3; border-bottom: 2px solid #3d8bff; }
QMenuBar::item:disabled { color: #3a4a6b; }

/* popup menus: double-framed, dim selected (inverted) */
QMenu { background: #0d1424 !important; border: 3px solid #1c2c4a; padding: 6px; font-size: 12px; }
QMenu::item { padding: 7px 26px 7px 14px; background: transparent !important; color: #dce6f7; letter-spacing: 2px; }
QMenu::item:selected { background: #070c16 !important; color: #5f7ba3; border-left: 3px solid #3d8bff; }
QMenu::item:disabled { color: #3a4a6b; }
QMenu::separator { height: 2px; background: #1c2c4a; margin: 6px 10px; }

/* toolbar: flat, oversized tracking, inverted active (dim) */
QToolBar { background: #0a1220 !important; border: none; border-bottom: 1px solid #1c2c4a; spacing: 3px; padding: 4px; qproperty-iconSize: 24px 24px; }
QToolBar::separator { background: #1c2c4a; width: 1px; margin: 6px 5px; }
QToolBar QToolButton, QToolButton { background: transparent !important; padding: 6px 12px; border: 1px solid transparent; color: #94a8cc; letter-spacing: 2px; font-size: 12px; }
QToolBar QToolButton:hover, QToolButton:hover { background: #16233d !important; border: 1px solid #2c4470; color: #3d8bff; }
QToolBar QToolButton:checked, QToolBar QToolButton:pressed,
QToolButton:checked, QToolButton:pressed { background: #070c16 !important; border: 1px solid #3d8bff; color: #5f7ba3; }

/* buttons: double-border cards */
QPushButton {
    background: #0d1424 !important;
    border: 2px solid #1c2c4a; border-radius: 2px; padding: 8px 22px;
    color: #dce6f7; font-weight: 600; letter-spacing: 3px; font-size: 12px;
}
QPushButton:hover { background: #16233d !important; border: 2px solid #3d8bff; color: #3d8bff; }
QPushButton:pressed { background: #3d8bff !important; color: #070c16; }
QPushButton:checked { background: #070c16 !important; border: 2px solid #3d8bff; color: #5f7ba3; }
QPushButton:default { border: 2px solid #3d8bff; }
QPushButton:disabled { background: #0a1220 !important; color: #3a4a6b; border: 2px solid #1c2c4a; }

/* inputs: double-border wells */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background: #04080f !important;
    border: 2px solid #1c2c4a; border-radius: 2px; padding: 7px 12px;
    color: #3d8bff; letter-spacing: 2px; font-size: 12px;
    selection-background-color: #3d8bff; selection-color: #070c16;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus { border: 2px solid #3d8bff; }
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled, QTextEdit:disabled, QPlainTextEdit:disabled { color: #3a4a6b; }
QSpinBox::up-button, QSpinBox::down-button, QDoubleSpinBox::up-button, QDoubleSpinBox::down-button { background: transparent !important; border: none; width: 16px; }

QComboBox { background: #04080f !important; border: 2px solid #1c2c4a; border-radius: 2px; padding: 7px 12px; color: #dce6f7; letter-spacing: 2px; font-size: 12px; }
QComboBox:hover { border: 2px solid #2c4470; }
QComboBox:focus { border: 2px solid #3d8bff; }
QComboBox::drop-down { border: none; background: transparent !important; width: 18px; }
QComboBox QAbstractItemView { background: #0d1424 !important; border: 2px solid #1c2c4a; padding: 5px; selection-background-color: #070c16; selection-color: #5f7ba3; }

QCheckBox, QRadioButton { color: #dce6f7; background: transparent !important; padding: 3px; letter-spacing: 2px; }
QCheckBox::indicator, QRadioButton::indicator { width: 16px; height: 16px; border-radius: 2px; background: #04080f !important; border: 2px solid #2c4470; }
QRadioButton::indicator { border-radius: 8px; }
QCheckBox::indicator:hover, QRadioButton::indicator:hover { border: 2px solid #3d8bff; }
QCheckBox::indicator:checked, QRadioButton::indicator:checked { background: #3d8bff !important; border: 2px solid #3d8bff; }

QTabBar::tab { background: transparent !important; color: #5f7ba3; padding: 9px 18px; border: 1px solid transparent; border-bottom: 2px solid transparent; letter-spacing: 3px; }
QTabBar::tab:hover { color: #dce6f7; }
QTabBar::tab:selected { color: #5f7ba3; border: 1px solid #3d8bff; border-bottom: 2px solid #3d8bff; }
QTabWidget::pane { border: none; border-top: 2px solid #1c2c4a; }

/* docks: tiled weave + double frame */
QDockWidget { background: qlineargradient(x1:0, y1:1, x2:0.25, y2:0, spread:repeat, stop:0 #101d36, stop:1 #0a1220) !important; border: 2px solid #1c2c4a; border-radius: 2px; }
QDockWidget::title {
    background: #0a1220 !important;
    border: none; border-bottom: 2px solid #1c2c4a; border-left: 4px solid #3d8bff;
    padding: 7px 12px; color: #94a8cc; font-weight: 700; letter-spacing: 2px;
}
QDockWidget::close-button, QDockWidget::float-button { background: transparent !important; border: 1px solid transparent; border-radius: 2px; padding: 3px; icon-size: 18px; }
QDockWidget::close-button:hover, QDockWidget::float-button:hover { background: #16233d !important; }

QGroupBox { background: transparent !important; border: 2px solid #1c2c4a; border-radius: 2px; margin-top: 13px; padding-top: 11px; }
QGroupBox::title { subcontrol-origin: margin; subcontrol-position: top left; padding: 0 10px; color: #3d8bff; font-weight: 700; letter-spacing: 2px; background: #070c16; }

/* item views: INVERTED selection — active row is DIM, others bright */
QAbstractItemView {
    background: #04080f !important; border: 2px solid #1c2c4a; border-radius: 2px;
    outline: none; alternate-background-color: #0a1220;
    selection-background-color: #070c16; selection-color: #5f7ba3; font-size: 12px;
}
QAbstractItemView::item { padding: 6px 12px; border: none; border-left: 3px solid transparent; border-bottom: 1px solid #1c2c4a; color: #dce6f7; letter-spacing: 1px; }
QAbstractItemView::item:hover { background: #16233d !important; color: #3d8bff; }
QAbstractItemView::item:selected { background: #070c16 !important; color: #5f7ba3; border-left: 3px solid #3d8bff; }
QTreeView::branch { background: transparent !important; }
QHeaderView::section { background: #0a1220 !important; border: none; border-bottom: 2px solid #1c2c4a; padding: 7px 12px; color: #94a8cc; font-weight: 700; letter-spacing: 3px; }

QScrollBar:vertical { background: #04080f; width: 11px; margin: 0; border: none; }
QScrollBar::handle:vertical { background: #2c4470; border-radius: 2px; min-height: 32px; }
QScrollBar::handle:vertical:hover { background: #3d8bff; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; border: none; background: none; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: none; }
QScrollBar:horizontal { background: #04080f; height: 11px; margin: 0; border: none; }
QScrollBar::handle:horizontal { background: #2c4470; border-radius: 2px; min-width: 32px; }
QScrollBar::handle:horizontal:hover { background: #3d8bff; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0; border: none; background: none; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: none; }
QScrollBar::corner { background: none; }

QSlider::groove:horizontal { background: #04080f; border: 2px solid #1c2c4a; height: 8px; border-radius: 2px; }
QSlider::sub-page:horizontal { background: #3d8bff; border-radius: 2px; }
QSlider::add-page:horizontal { background: #04080f; border-radius: 2px; }
QSlider::handle:horizontal { background: #3d8bff; width: 14px; height: 16px; margin: -6px 0; border: 2px solid #070c16; border-radius: 2px; }
QSlider::handle:horizontal:hover { background: #7ab0ff; }
QSlider::groove:vertical { background: #04080f; border: 2px solid #1c2c4a; width: 8px; border-radius: 2px; }
QSlider::sub-page:vertical { background: #3d8bff; border-radius: 2px; }
QSlider::handle:vertical { background: #3d8bff; width: 16px; height: 14px; margin: 0 -6px; border: 2px solid #070c16; border-radius: 2px; }

QProgressBar { background: #04080f; border: 2px solid #1c2c4a; border-radius: 2px; text-align: center; color: #94a8cc; font-size: 11px; letter-spacing: 3px; min-height: 16px; }
QProgressBar::chunk { background: #3d8bff; border-radius: 2px; }

QStatusBar { background: #0a1220 !important; border-top: 2px solid #1c2c4a; color: #5f7ba3; font-size: 11px; letter-spacing: 2px; }
QStatusBar::item { border: none; }
QToolTip { background: #0d1424 !important; border: 2px solid #3d8bff; border-radius: 2px; padding: 6px 12px; color: #dce6f7; }
QSplitter::handle { background: #1c2c4a; }
QSplitter::handle:hover { background: #3d8bff; }
QListView, QListWidget, QTreeWidget, QTableWidget { background: #04080f !important; border: 2px solid #1c2c4a; border-radius: 2px; outline: none; }
